THREADS=[]
def thread(k,title,kind,status,ks,es,note,nums,resolution=None):
 ns={'v05-s-'+x for x in ks};eids={'v05-e-'+x for x in es}
 for e in EDGES:
  if e['id'] in eids:ns.update([e['from'],e['to']])
 r=dict(id='v05-t-'+k,title=title,kind=kind,status=status,node_ids=sorted(ns),edge_ids=sorted(eids),stage_note=note,claim_kind='inference',evidence=ev(nums))
 if resolution:r.update(resolution_note=resolution,resolution_evidence=ev(nums))
 THREADS.append(r)
